import "./NavBar.css";
import ChatLogo from "../../SVG/ChatLogo";
import NotificationLogo from "../../SVG/NotificationLogo";
import Logo from "../Img/Logo.jpeg";
import { useDispatch, useSelector } from "react-redux";
import { LogOut, selectUser } from "../../store/slices/UserSlice";
import { NavLink, useNavigate } from "react-router-dom";
const NavBar = () => {
  const navigate = useNavigate();
  const {profile} = useSelector(selectUser);
  const dispatch = useDispatch();

  const logOut = () => {
    fetch(`http://localhost:3005/users_Data/${profile?.id}`, {
      method: "PUT",
      body: JSON.stringify(profile),
    });

    fetch(`http://localhost:3005/Loged_User/${profile.id}`, {
      method: "DELETE",
    });
    dispatch(LogOut());
    navigate("/Login");
  };
  console.log(profile);
  
  const FindImage = profile?.Photo?.map((el) => {
    if(el.key){
      return el.url
    } else {
      return ''
    }
  });
  return (
    <nav className="NavBar">
      <div className="LogoSide">
        <img
          src={Logo}
          alt="Logo"
          onClick={() => {
            if (profile.length === 0) {
              navigate("/Login");
            } else {
              navigate("/profile");
            }
          }}
        />
        <input type="text" placeholder="Search people,jops & more" />
      </div>
      <div className="JobSide">
        <ul>

          <li><NavLink to={"Pages"}>Pages</NavLink></li>
          <li>
            <ChatLogo />
          </li>
          <li>
            <NotificationLogo />
          </li>
          <li>
            <img src={profile?.image} alt="" />
          </li>
         
          <li className="LogOut" onClick={logOut}>
            Log Out
          </li>
        </ul>
      </div>
    </nav>
  );
};

export default NavBar;
